"""Application explanations, independently written after checking pinned 1920/1914 originals."""
import json,hashlib
from pathlib import Path
root=Path(__file__).resolve().parents[2]
sources=[('smyth','agreekgrammarfo02smytgoog','1920'),('robertson','grammarofgreekne00robe_0','1914')]
entries=[]
def entry(source,category,ident,title,locator,page,summary,can,cannot):
 archive=next(x[1] for x in sources if x[0]==source); year=next(x[2] for x in sources if x[0]==source); url=f'https://archive.org/details/{archive}/page/{page}/mode/2up'
 entries.append(dict(id=ident,category=category,title=title,summary=summary,canEstablish=can,cannotEstablish=cannot,url=url,locator=locator,provenance=dict(source=source,edition=f'{source.title()} ({year})',version=f'{year}-original-checked-2026-10-26',license='Public-Domain (underlying original); application paraphrase MIT',locator=locator,reviewStatus='upstream',deepLink=f'/grammar?id={ident}',upstreamUrl=url)))
entry('smyth','agreement','smyth-concord','Agreement and construction according to sense','Smyth §§925–926, pp. 258–259','258','Application explanation: Smyth distinguishes ordinary concord from construction according to sense and attraction. These categories require examination of the actual construction.','A mismatch in grammatical gender can be identified and compared with documented agreement according to sense.','A gender mismatch alone cannot rule out a referent or decide whether a command addresses nations corporately or people within them.')
entry('robertson','referent','robertson-matt-28-19','Personal pronouns according to sense: Matthew 28:19','Robertson, ch. XV.I(e), pp. 683–684','684','Application explanation: In his discussion of personal pronouns according to sense, Robertson explicitly relates αὐτούς in Matthew 28:19 to ἔθνη. He compares other pronoun usages involving grammatical and natural gender.','A documented grammarian treats the masculine pronoun as referring to the neuter noun; grammatical gender alone does not make that reference impossible.','This observation does not independently establish a corporate political, covenantal, or exclusively individual interpretation, or any baptismal policy.')
entry('smyth','gender','smyth-gender','Grammatical and natural gender','Smyth §§196–197, p. 45','45','Application explanation: Greek has masculine, feminine and neuter grammatical gender. Grammatical gender and the sex or personhood of a referent are distinct; masculine forms may designate mixed classes.','Gender is a feature of the annotated Greek form, useful for agreement checks.','Neuter does not mean inanimate and masculine does not mean only male persons. Gender cannot by itself determine the social extent of a referent.')
entry('smyth','number','smyth-number','Number','Smyth §195, p. 45','45','Application explanation: Singular, dual and plural are inflectional categories. The NT annotations in this pack primarily distinguish singular and plural.','The form can be classified as singular or plural in the supplied analysis.','Plural alone cannot decide between collective and distributive interpretations, or count the people intended.')
entry('smyth','case','smyth-case','Case and agreement','Smyth §§925–927, pp. 258–259','259','Application explanation: Case constrains syntactic relations; the subject of a finite verb is ordinarily nominative, and apposition involves case concord. Each construction still requires syntactic analysis.','Case can constrain candidate syntactic relations when combined with verb and clause structure.','An accusative is not always a direct object, and a genitive does not by itself select one English relationship or theological conclusion.')
entry('smyth','person','smyth-person','Person and number in finite verbs','Smyth §925.1, p. 258','258','Application explanation: Finite verbs ordinarily agree with their subjects in person and number.','A second-person plural finite form addresses a plural grammatical subject.','Person and number do not identify all implied participants or the scope of every later application of a command.')
entry('smyth','tense','smyth-aorist','Aorist and duration','Smyth §1923, p. 479','479','Application explanation: Smyth describes the aorist indicative as presenting a past event without specifying how long it occupied. Other moods must not be assigned past time merely from the aorist stem.','An aorist annotation identifies the tense stem; context and mood determine its use.','Aorist does not itself establish instantaneous, once-for-all or unrepeatable action. An aorist imperative is not thereby a past-time command.')
for category,title,summary,can,cannot in [('voice','Voice','Voice describes the relation of the subject to the verbal action. Middle and passive forms and meanings need to be distinguished in context.','The upstream analysis supplies an active, middle or passive classification.','A voice label alone cannot decide the identity of an unexpressed agent or whether a traditional deponent label resolves the semantics.'),('mood','Mood and verbal nouns','Greek distinguishes indicative, subjunctive, optative and imperative; infinitives and participles are verbal nouns in the traditional classification.','The annotation identifies a formal category for interpreting the clause.','An imperative alone does not identify every intended recipient; a participle does not automatically mean a temporal sequence or a second independent command.'),('partOfSpeech','Parts of speech and verbal forms','Inflected forms must be interpreted in their phrase and clause; participles combine verbal and nominal properties.','The imported part-of-speech category supports a plain-language parse.','A part-of-speech tag alone cannot supply a missing argument, word sense or discourse function.')]:
 entry('smyth',category,'smyth-'+category,title,'Smyth, Inflection: voices, moods and verbal nouns, p. 107','107','Application explanation: '+summary,can,cannot)
(root/'data/grammar/entries.json').write_text(json.dumps(entries,ensure_ascii=False,indent=2)+'\n')
p=root/'data/manifests/grammar-sources.json'; notices=[]
for source,archive,year in sources:
 path=next((root/'data/downloads'/source).glob('*_djvu.txt'));b=path.read_bytes();notices.append(dict(id=source,edition=year,upstreamUrl=f'https://archive.org/details/{archive}',file=dict(path=path.relative_to(root/'data/downloads').as_posix(),url=f'https://archive.org/download/{archive}/{path.name}',sha256=hashlib.sha256(b).hexdigest()),included=['Verified section/page locators','Application-authored bounded explanations'],excluded=['Full OCR transcription','Digital scans','Perseus/Alpheios NC markup'],license='Public-domain underlying original; no scan/markup redistribution claimed'))
p.write_text(json.dumps(notices,ensure_ascii=False,indent=2)+'\n')
